import{z as c,x as d,o as E,c as l,q as t,j as r,D as a,d as s,s as A,S as n}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"收包路径的解剖","description":"","frontmatter":{"title":"收包路径的解剖","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/npk-rx-path.md","filePath":"cs/npk-rx-path.md","lastUpdated":1791063341000}'),i={name:"cs/npk-rx-path.md"};function B(p,e,_,m,h,k){const o=d("Mermaid");return E(),l("div",null,[e[2]||(e[2]=t('<h1 id="收包路径的解剖" tabindex="-1">收包路径的解剖 <a class="header-anchor" href="#收包路径的解剖" aria-label="Permalink to &quot;收包路径的解剖&quot;">​</a></h1><div class="epigraph"><p>应用看见的「可读」是一个事件；把它生产出来的是一条由中断、预算、队列与内存会计串成的流水线，每一节都有容量，每一节都会丢。</p><footer>—— 据 Benvenuti, <em>Understanding Linux Network Internals</em>；Linux 内核对 NAPI 与 softirq 预算的文档整理</footer></div><p><a href="/cs/osk-map">上一课</a>给「操作系统内核实践」收束：执行流、地址、数据、同步入口、异步入口、失效面六课一条装配主线，四条不变量各堵一个已知的装配失效——主干给零件图，本课程给总装图。网络协议栈照同一个读法拆：主干课的<a href="/cs/socket-nonblock">阻塞与非阻塞套接字</a>把应用侧的合同钉在「就绪」上——阻塞读睡着等，非阻塞读立即返回 EAGAIN，再靠多路复用回来；<a href="/cs/tcp-handshake">三次握手</a>、<a href="/cs/tcp-seq-rexmit">序号与重传</a>、<a href="/cs/tcp-window">流控窗口</a>被当协议拆过；操作系统课也用<a href="/cs/rx-path">接收路径</a>把函数链串过一遍。本课程「网络协议栈实践」开始把每一段拆开当程序读。第一课解剖收包路径：一帧从网卡内存到进程被唤醒，经过几段队列、几次上下文切换、哪些检查点会丢包。后课默认你已读过这条路径。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>应用层的观感是「有数据了」；实现层要回答的是预算问题：软中断一次最多干多少活、socket 队列最多装多少字节、装不下时谁被丢。不这么做会错在哪：把丢包一律归咎网卡或对端，会漏掉最常见的第三类——网卡计数器干净、线上也干净，包丢在软中断预算耗尽之后的 backlog 队列或 socket 内存会计上；这三类丢包各有各的计数器，混在一起就查不下去。</p><p><span class="marginnote">术语翻译：NAPI 就是「别每来一个包都按一次门铃」的手段——硬中断只按一次铃说「有货了」，然后 CPU 自己下到收货台（驱动环）按预算批量盘点，盘点期间门铃先关掉。包越密，省下的门铃（中断）次数越多。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>逐段解剖。入口：网卡 DMA 把帧写进接收环，硬中断只做一件事——登记 NAPI 并调度软中断，然后把中断关掉，否则每个包都打断一次 CPU。轮询：软中断 <code>net_rx_action</code> 在预算内循环调驱动 poll，一次预算默认三百个包、八毫秒上限，单设备单轮权重六十四；预算花完，剩余帧留在 backlog 队列等下一轮，<code>time_squeeze</code> 计数器加一。合并：GRO 把同流的小帧并成最大六十四 KB 的逻辑包再交协议栈，协议栈每字节只跑一次。分发：<code>eth_type_trans</code> 认出 IPv4 后，<code>ip_rcv</code> 过 netfilter 钩子，本机交付走 <code>tcp_v4_rcv</code>，用四元组哈希在 established 表里一次查出 sock——early demux 在此之前先把查到的 sock 缓存下来，省掉一次路由查找。入队：skb 计入该 sock 的 rmem 会计，超限则修剪队列甚至丢包，成功则挂进接收队列并执行 <code>sk_data_ready</code> 唤醒读者——这正是主干课<a href="/cs/socket-nonblock">阻塞与非阻塞套接字</a>「就绪」合同的生产端。</p>',8)),(E(),r(n,null,{default:a(()=>[A(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20RING%5B%22%E7%BD%91%E5%8D%A1%E6%8E%A5%E6%94%B6%E7%8E%AF%EF%BC%88DMA%EF%BC%89%22%5D%20--%3E%20IRQ%5B%22%E7%A1%AC%E4%B8%AD%E6%96%AD%EF%BC%9A%E7%99%BB%E8%AE%B0%20NAPI%20%E5%8D%B3%E8%BF%94%E5%9B%9E%22%5D%0A%20%20IRQ%20--%3E%20POLL%5B%22%E8%BD%AF%E4%B8%AD%E6%96%AD%EF%BC%9A%E9%A2%84%E7%AE%97%E5%86%85%E8%BD%AE%E8%AF%A2%22%5D%0A%20%20POLL%20--%3E%20GRO%5B%22GRO%20%E5%90%88%E5%B9%B6%22%5D%0A%20%20GRO%20--%3E%20IP%5B%22ip_rcv%20%E4%B8%8E%20netfilter%22%5D%0A%20%20IP%20--%3E%20TCP%5B%22tcp_v4_rcv%20%E6%9F%A5%20sock%22%5D%0A%20%20TCP%20--%3E%20Q%5B%22sk%20%E6%8E%A5%E6%94%B6%E9%98%9F%E5%88%97%EF%BC%88rmem%20%E4%BC%9A%E8%AE%A1%EF%BC%89%22%5D%0A%20%20Q%20--%3E%20WAKE%5B%22sk_data_ready%20%E5%94%A4%E9%86%92%E8%AF%BB%E8%80%85%22%5D%0A%20%20POLL%20--%3E%7C%22%E9%A2%84%E7%AE%97%E8%80%97%E5%B0%BD%22%7C%20BACK%5B%22backlog%20%E9%98%9F%E5%88%97%E7%AD%89%E4%B8%8B%E4%B8%80%E8%BD%AE%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=t('<p><span class="marginnote">数字实例：GRO 把 1500 字节的小帧并成最大 64 KB 的逻辑包，一次最多约合 43 个帧。合并后 <code>ip_rcv</code>、netfilter、协议栈入口整条流水线只走 1 次而不是 43 次——这就是「合并」省的不是复制，而是每层检查的固定开销。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>这套组织的理由是摊销与记账。中断只付一次「有包」的通知成本，批量轮询把固定成本摊到整批，代价是预算内的包要等轮询结束——这是延迟与 CPU 的交换。每层剥头不复制，六十四字节的以太网头到 TCP 头一路是同一块 skb 换偏移。内存会计把「谁吃光内核内存」钉到每个 sock：慢读者不会拖垮全机，只会压低自己的通告窗口——这是<a href="/cs/socket-buffers">套接字缓冲与背压</a>的机制在收包路径上的执行点。多核下 RSS 先按流哈希选队列，RFS 再把协议栈处理搬到应用所在的核，付一次跨核通知换缓存亲和（<a href="/cs/rss-multiqueue">RSS 与多队列</a>）。丢包点各有名字：backlog 溢出记 <code>TCPBacklogDrop</code>，socket 队列修剪记 <code>PruneCalled</code>，软中断丢帧记 softnet_stat 第二列。</p><p><span class="marginnote">预算的默认值值得背下来：<code>net.core.netdev_budget</code> 300、<code>netdev_budget_usecs</code> 8000 微秒、单轮权重 64。10 GbE 线速小包约 14.88 Mpps，每个软中断循环只处理 300 包——预算跟不上线速时，包根本没到协议栈就积压在驱动环里，<code>rx_missed</code> 类网卡计数器先涨。</span></p><p><span class="marginnote">常见误区：接收吞吐上不去就怀疑网络或网卡。若同连接的通告窗口在缩，先看本机应用是不是读得慢——rmem 会计超限时被压低的是「自己这条连接」的窗口，慢读者只拖垮自己，不拖垮全机。窗口缩小的病灶常在接收端的应用线程，不在链路。</span></p>',5)),(E(),r(n,null,{default:a(()=>[A(o,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%A4%9A%E6%A0%B8%E4%B8%8B%E8%BF%99%E4%B8%AA%E5%8C%85%E4%BA%A4%E7%BB%99%E5%93%AA%E4%B8%AA%20CPU%3F%22%5D%20--%3E%20RSS%5B%22RSS%3A%20%E6%8C%89%E6%B5%81%E5%93%88%E5%B8%8C%E9%80%89%E7%A1%AC%E4%BB%B6%E9%98%9F%E5%88%97%22%5D%0A%20%20RSS%20--%3E%20IRQC%5B%22%E4%B8%AD%E6%96%AD%E8%90%BD%E5%9C%A8%E9%98%9F%E5%88%97%E7%BB%91%E5%AE%9A%E7%9A%84%E6%A0%B8%22%5D%0A%20%20IRQC%20--%3E%20RFS%5B%22RFS%3A%20%E8%AE%B0%E4%B8%8B%E6%B5%81%E5%AF%B9%E5%BA%94%E7%9A%84%E5%BA%94%E7%94%A8%E5%9C%A8%E5%93%AA%E4%B8%AA%E6%A0%B8%22%5D%0A%20%20RFS%20--%3E%20STEER%5B%22%E6%8A%8A%E5%8D%8F%E8%AE%AE%E6%A0%88%E5%A4%84%E7%90%86%E6%90%AC%E5%88%B0%E5%BA%94%E7%94%A8%E6%89%80%E5%9C%A8%E6%A0%B8%22%5D%0A%20%20STEER%20--%3E%20CACHE%5B%22%E5%91%BD%E4%B8%AD%E5%BA%94%E7%94%A8%20CPU%20%E7%9A%84%E7%BC%93%E5%AD%98%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[s(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重讲 <a href="/cs/gro-gso">GRO 与 GSO</a> 的合并规则，不展开 <a href="/cs/netfilter-conntrack">netfilter</a> 的表与链，转发路径（本机不是终点）与 XDP 的驱动层分流也不在此——那是<a href="/cs/hpc-kernel-bypass">内核旁路</a>的世界，本课程只承认它在更早的检查点上就能把包拿走。虚拟化里的 veth 与网桥变形不在本课。后课默认：包到 TCP 时已在 sk 接收队列里，唤醒路径成立；下一课把 TCP 拿到包之后怎么记账——状态机——拆开。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>收包路径是一条预算链：中断只通知，软中断按预算轮询，超支的包排队或被丢。</li><li>early demux 与四元组哈希让「找 sock」一次命中；rmem 会计把丢包责任钉到单个连接。</li><li>三类丢包（网卡环、backlog、socket 队列）各有独立计数器，排障必须分层对号。</li><li>「可读」事件由 <code>sk_data_ready</code> 生产，是阻塞与非阻塞合同在内核里的落点。</li><li>出处：Benvenuti, <em>Understanding Linux Network Internals</em>；Linux 内核 NAPI/softirq 文档；Stevens, <em>UNIX Network Programming</em>。</li></ul>',4))])}const C=c(i,[["render",B]]);export{f as __pageData,C as default};
